def place_on_zone_v2(obj_name, zone_name):
    obs = observe()
    zone = obs["zones"][zone_name]
    zone_center = zone["center"]
    rim_height = zone.get("rim_height", 0.0)

    if not pick_object(obj_name):
        return False

    place_at_position(zone_center[0], zone_center[1], clear_height=rim_height + 0.15, retreat_height=0.15)
    go_home()
    return check(obj_name, zone_name)

def place_on_zone_v7(obj_name, zone_name):
    obs = observe()
    zone = obs["zones"][zone_name]
    zone_center = zone["center"]
    rim_height = zone.get("rim_height", 0.08)
    table_z = obs["table_z"]

    if not grasp_elongated_object(obj_name, min_height=0.012):
        return False

    safe_z = table_z + rim_height + 0.15
    carry_to(zone_center[0], zone_center[1], height=safe_z - table_z)

    if not reorient_held_object_upright(zone_center[0], zone_center[1], safe_z):
        return False

    return drop_into_container_v2(obj_name, zone_name, safe_z_offset=0.15)

